$ErrorActionPreference = "Stop"

$desktop = [Environment]::GetFolderPath('Desktop')
$imgDir = Join-Path $desktop 'AI_Attendance_Images'
$tempDir = Join-Path $desktop 'AI_Attendance_Image_Html'
$edge = 'C:\Program Files (x86)\Microsoft\Edge\Application\msedge.exe'

New-Item -ItemType Directory -Force -Path $imgDir | Out-Null
New-Item -ItemType Directory -Force -Path $tempDir | Out-Null
Get-ChildItem -LiteralPath $imgDir -File -ErrorAction SilentlyContinue | Remove-Item -Force

function Export-Image {
    param(
        [string]$BaseName,
        [string]$Html
    )

    $htmlPath = Join-Path $tempDir ($BaseName + '.html')
    $imgPath = Join-Path $imgDir ($BaseName + '.png')
    Set-Content -LiteralPath $htmlPath -Value $Html -Encoding UTF8
    & $edge --headless --disable-gpu --window-size=1240,1754 --screenshot="$imgPath" "file:///$htmlPath" | Out-Null
    Start-Sleep -Milliseconds 1200
}

